function getToday() {
  const d = new Date();
  const yyyy = d.getFullYear();
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return `${yyyy}/${mm}/${dd}`;
}

function cleanText(value, maxLength = 0) {
  const text = String(value ?? '').replace(/\s+/g, ' ').trim();
  if (!maxLength || text.length <= maxLength) return text;
  return `${text.slice(0, maxLength)}...`;
}

const today = getToday();
const articles = items.map((item, index) => ({
  index: index + 1,
  title: cleanText(item.json.title),
  url: cleanText(item.json.url),
  journal: cleanText(item.json.journal),
  date: cleanText(item.json.date),
  summary: cleanText(item.json.summary, 1800),
  englishAbstract: cleanText(item.json.summary, 6000),
}));

let html = `\n<h2 style="color:#8b1e3f;">每日臨床頂級期刊速報（${today}）</h2>\n<ol>\n`;
let llmInput = `這是我為您準備的頂級期刊文獻清單（共 ${articles.length} 篇）：\n\n`;

for (const article of articles) {
  html += `
  <li style="margin-bottom: 16px;">
    <div>
      <a href="${article.url}" style="font-size:1.05em; color:#8b1e3f; text-decoration:underline; font-weight:bold;">
        ${article.title}
      </a>
    </div>
    <ul style="list-style:none; padding-left:0; margin-top:6px; margin-bottom:6px;">
      <li><b>期刊：</b>${article.journal}</li>
      <li><b>出版日期：</b>${article.date}</li>
      <li><b>摘要：</b>${article.summary || '未提供'}</li>
    </ul>
  </li>
  `;

  llmInput += `【第 ${article.index} 篇】\n`;
  llmInput += `標題：${article.title}\n`;
  llmInput += `連結：${article.url}\n`;
  llmInput += `背景資料：發表於 ${article.journal} (${article.date})\n`;
  llmInput += `摘要：${article.summary || '未提供'}\n\n`;
}

html += '</ol>';

return [{
  json: {
    emailBody: html,
    llmInput,
    articles,
    articleCount: articles.length,
    reportDate: today,
  }
}];

// 遍歷每一筆資料
for (const item of $input.all()) {

  // 1. 取得原始資料 (防呆：確保它是字串)
  const rawData = item.json.data;
  let finalOutput = 'No abstract provided'; // 預設值

  // 確保 rawData 是字串才處理，避免報錯
  if (typeof rawData === 'string') {

    // 2. 步驟 1: 抓取 Abstract 區塊 (你的原始 Regex)
    const match = rawData.match(/<Abstract>(.*?)<\/Abstract>/s);

    if (match && match[1]) {
      let txt = match[1];

      // 3. 步驟 2 & 3: 執行你的清理邏輯
      txt = txt.replace(/<AbstractText[^>]*>/g, '\n\n'); // 保留段落
      txt = txt.replace(/<[^>]+>/g, '');                 // 移除所有 XML/HTML 標籤
      txt = txt.replace(/&#x[0-9a-fA-F]+;/g, ' ');       // 移除 HTML 實體編碼
      txt = txt.replace(/\s+/g, ' ').trim();             // 清理多餘空白

      finalOutput = txt;
    }
  }

  // 4. 將結果寫入新欄位 'cleaned_content'
  // 這樣你在下一個節點就能清楚看到這個欄位
  item.json.cleaned_content = finalOutput;
}

return $input.all();

function cleanText(value, maxLength = 0) {
  const text = String(value ?? '').replace(/\s+/g, ' ').trim();
  if (!maxLength || text.length <= maxLength) return text;
  return `${text.slice(0, maxLength)}...`;
}

const triage = $json.triage || {};
const selected = Array.isArray($json.shortlistedArticles) ? $json.shortlistedArticles : [];

const normalizedArticles = selected.map((article, index) => ({
  index: index + 1,
  originalIndex: Number(article.originalIndex || article.index || index + 1),
  title: cleanText(article.title),
  url: cleanText(article.url),
  journal: cleanText(article.journal),
  date: cleanText(article.date),
  triageTier: cleanText(article.triageTier),
  triageReason: cleanText(article.triageReason, 180),
  triagePriorityScore: Number.isFinite(Number(article.triagePriorityScore)) ? Math.round(Number(article.triagePriorityScore)) : 0,
  englishAbstract: cleanText(article.englishAbstract || article.summary, 12000),
}));

const preclassifiedTier3 = Array.isArray($json.preTier3)
  ? $json.preTier3.map((item) => ({
      title: cleanText(item.title, 220),
      titleZhNote: cleanText(item.titleZhNote, 120),
      url: cleanText(item.url),
      journal: cleanText(item.journal, 120),
      date: cleanText(item.date, 60),
      reason: cleanText(item.reason, 80),
    }))
  : [];

const payload = {
  reportDate: $json.reportDate || new Date().toISOString().slice(0, 10),
  articleCount: Number($json.articleCount || normalizedArticles.length),
  shortlistedCount: normalizedArticles.length,
  preclassifiedTier3Count: preclassifiedTier3.length,
  triageNote: cleanText(triage.note, 220),
  instruction: 'shortlist 文章都保留完整英文摘要供 deep analysis 使用。已在前一步被放進 preclassifiedTier3 的文章，只有標題與簡短資料，最後只需簡短列過，不需要重新分析研究內容。請把主要筆力放在 shortlist 的 tier1 與 tier2。',
  articles: normalizedArticles,
  preclassifiedTier3,
};

const text = JSON.stringify(payload, null, 2);

return {
  json: {
    ...$json,
    shortlistedCount: normalizedArticles.length,
    shortlistedArticles: normalizedArticles,
    preTier3: preclassifiedTier3,
    text,
    textPreview: text.slice(0, 500),
    length: text.length,
  }
};

function getRawModelOutput(input) {
  const direct = input?.text ?? input?.data ?? input?.body ?? '';
  const raw = typeof direct === 'string' ? direct : JSON.stringify(direct ?? '');
  const trimmed = String(raw ?? '').trim();
  if (!trimmed) return trimmed;

  if (trimmed.startsWith('data:')) {
    const lines = trimmed.split(/\r?\n/);
    let assembled = '';
    for (const rawLine of lines) {
      const line = rawLine.trim();
      if (!line.startsWith('data:')) continue;
      const payload = line.slice(5).trim();
      if (!payload || payload === '[DONE]') continue;
      try {
        const parsed = JSON.parse(payload);
        const choice = parsed?.choices?.[0] || {};
        const delta = choice?.delta || {};
        const piece = delta?.content ?? choice?.message?.content ?? choice?.text ?? '';
        if (piece) assembled += piece;
      } catch {}
    }
    if (assembled.trim()) return assembled.trim();
  }

  try {
    const parsed = JSON.parse(trimmed);
    const choice = parsed?.choices?.[0] || {};
    const content = choice?.message?.content ?? choice?.text ?? '';
    if (content) return String(content).trim();
  } catch {}

  return trimmed;
}

function getStreamErrorMessage(raw) {
  const text = String(raw ?? '').trim();
  if (!text.includes('event: error')) return '';
  const lines = text.split(/\r?\n/);
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (line !== 'event: error') continue;
    const next = String(lines[i + 1] ?? '').trim();
    if (!next.startsWith('data:')) return 'stream error';
    const payload = next.slice(5).trim();
    try {
      const parsed = JSON.parse(payload);
      return parsed?.error?.message || parsed?.message || 'stream error';
    } catch {
      return payload || 'stream error';
    }
  }
  return 'stream error';
}

function stripFence(text) {
  const value = String(text ?? '').trim();
  const fenceMatch = value.match(/```(?:json)?\s*([\s\S]*?)```/i);
  return fenceMatch ? fenceMatch[1].trim() : value;
}

function repairJsonLike(value) {
  let repaired = String(value ?? '').trim();
  repaired = repaired
    .replace(/[“”]/g, '"')
    .replace(/[‘’]/g, "'")
    .replace(/,\s*([}\]])/g, '$1')
    .replace(/\r/g, '');

  repaired = repaired.replace(/:\s*「([^」]+)」([^,}\]\n]*)/g, (_, inner, rest) => {
    const tail = String(rest || '').trim();
    const content = tail ? `「${inner}」${tail}` : `「${inner}」`;
    return `: "${content.replace(/"/g, '\\"')}"`;
  });

  repaired = repaired.replace(/:\s*([^"{\[\]\d\-][^,}\]\n]*)(?=\s*[,}\]])/g, (match, rawValue) => {
    const valueText = String(rawValue ?? '').trim();
    if (!valueText) return ': ""';
    if (['true', 'false', 'null'].includes(valueText)) return `: ${valueText}`;
    if (/^-?\d+(?:\.\d+)?$/.test(valueText)) return `: ${valueText}`;
    return `: "${valueText.replace(/"/g, '\\"')}"`;
  });

  repaired = repaired.replace(/(\n\s*}\s*),?(\n\s*"tier[23]"\s*:)/g, '$1],$2');
  return repaired;
}

function completeBrackets(text) {
  let repaired = String(text ?? '');
  const openBraces = (repaired.match(/\{/g) || []).length;
  const closeBraces = (repaired.match(/\}/g) || []).length;
  const openBrackets = (repaired.match(/\[/g) || []).length;
  const closeBrackets = (repaired.match(/\]/g) || []).length;
  repaired += ']'.repeat(Math.max(0, openBrackets - closeBrackets));
  repaired += '}'.repeat(Math.max(0, openBraces - closeBraces));
  return repaired;
}

function decodeJsonStringLiteral(str) {
  try {
    return JSON.parse(`"${String(str).replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\n/g, '\\n')}"`);
  } catch {
    return String(str ?? '');
  }
}

function extractField(text, field) {
  const regex = new RegExp(`"${field}"\\s*:\\s*"((?:\\\\.|[^"\\\\])*)"`, 'm');
  const match = String(text).match(regex);
  return match ? decodeJsonStringLiteral(match[1]) : '';
}

function extractCounts(text) {
  const match = String(text).match(/"counts"\s*:\s*\{([\s\S]*?)\}/m);
  if (!match) return null;
  try {
    return JSON.parse(`{${match[1]}}`);
  } catch {
    const counts = {};
    for (const key of ['total', 'tier1', 'tier2', 'tier3']) {
      const itemMatch = match[1].match(new RegExp(`"${key}"\\s*:\\s*(\\d+)`));
      if (itemMatch) counts[key] = Number(itemMatch[1]);
    }
    return counts;
  }
}

function findMatchingBracket(text, startIndex) {
  let depth = 0;
  let inString = false;
  let escape = false;
  for (let i = startIndex; i < text.length; i++) {
    const ch = text[i];
    if (escape) { escape = false; continue; }
    if (ch === '\\') { escape = true; continue; }
    if (ch === '"') { inString = !inString; continue; }
    if (inString) continue;
    if (ch === '[') depth++;
    else if (ch === ']') {
      depth--;
      if (depth === 0) return i;
    }
  }
  return -1;
}

function findTierStart(src, field) {
  const regex = new RegExp(`\\n\\s*"${field}"\\s*:\\s*\\[`, 'm');
  const match = regex.exec(src);
  if (!match) return -1;
  return src.indexOf('[', match.index);
}

function findNextTierKey(src, nextField, fromIndex) {
  if (!nextField) return -1;
  const regex = new RegExp(`\\n\\s*"${nextField}"\\s*:\\s*\\[`, 'm');
  const sliced = src.slice(fromIndex);
  const match = regex.exec(sliced);
  return match ? fromIndex + match.index : -1;
}

function extractTierArray(text, field, nextField) {
  const src = String(text ?? '');
  const startBracket = findTierStart(src, field);
  if (startBracket === -1) return [];

  let rawBlock = '';
  const nextPos = findNextTierKey(src, nextField, startBracket + 1);
  if (nextPos !== -1) {
    rawBlock = src.slice(startBracket, nextPos).replace(/,\s*$/, '').trim();
    if (!rawBlock.endsWith(']')) rawBlock += '\n]';
  } else {
    const naturalEnd = findMatchingBracket(src, startBracket);
    if (naturalEnd !== -1) {
      rawBlock = src.slice(startBracket, naturalEnd + 1);
    } else {
      const endPos = src.lastIndexOf('}');
      rawBlock = src.slice(startBracket, endPos).replace(/,\s*$/, '').trim();
      if (!rawBlock.endsWith(']')) rawBlock += '\n]';
    }
  }

  const attempts = [rawBlock, repairJsonLike(rawBlock), completeBrackets(repairJsonLike(rawBlock))];
  for (const attempt of attempts) {
    try {
      const parsed = JSON.parse(attempt);
      return Array.isArray(parsed) ? parsed : [];
    } catch {}
  }
  return [];
}

function salvageAnalysis(raw) {
  const text = stripFence(raw);
  const tier1 = extractTierArray(text, 'tier1', 'tier2');
  const tier2 = extractTierArray(text, 'tier2', 'tier3');
  const tier3 = extractTierArray(text, 'tier3', null);
  const counts = extractCounts(text) || {};
  const total = tier1.length + tier2.length + tier3.length;
  if (!tier1.length && !tier2.length && !tier3.length) {
    throw new Error('Unable to salvage any tiers from malformed JSON');
  }
  return {
    headline: extractField(text, 'headline') || '今日文獻快報',
    editorNote: extractField(text, 'editorNote') || '',
    counts: {
      total: counts.total || total,
      tier1: tier1.length,
      tier2: tier2.length,
      tier3: tier3.length,
    },
    tier1,
    tier2,
    tier3,
  };
}

function extractJson(raw) {
  const text = stripFence(raw);
  if (!text) throw new Error('Empty model output');
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  const block = start !== -1 && end !== -1 && end > start ? text.slice(start, end + 1) : text;
  const attempts = [block, repairJsonLike(block), completeBrackets(repairJsonLike(block))];
  for (const attempt of attempts) {
    try {
      return JSON.parse(attempt);
    } catch {}
  }
  throw new Error('JSON parse failed after repair attempts');
}

function normalizeText(value, maxLength = 0) {
  const text = String(value ?? '').replace(/\s+/g, ' ').trim();
  if (!maxLength || text.length <= maxLength) return text;
  return `${text.slice(0, maxLength)}...`;
}

function normalizeUrl(value) {
  const url = String(value ?? '').trim().replace(/\s+/g, '');
  if (!url) return '';
  if (url.startsWith('http://') || url.startsWith('https://')) return url;
  if (url.startsWith('www.')) return `https://${url}`;
  return url;
}

function normalizeKey(value) {
  return String(value ?? '').toLowerCase().replace(/\s+/g, ' ').trim();
}

function compactKey(value) {
  return String(value ?? '').toLowerCase().replace(/[^a-z0-9]+/g, '');
}

function buildArticleMaps(sourceArticles) {
  const byTitle = new Map();
  const byCompactTitle = new Map();
  for (const article of Array.isArray(sourceArticles) ? sourceArticles : []) {
    const normalized = {
      title: normalizeText(article.title),
      url: normalizeUrl(article.url),
      journal: normalizeText(article.journal),
      date: normalizeText(article.date),
    };
    const key = normalizeKey(article.title);
    const compact = compactKey(article.title);
    if (key) byTitle.set(key, normalized);
    if (compact) byCompactTitle.set(compact, normalized);
  }
  return { byTitle, byCompactTitle };
}

function getSourceArticle(item, maps) {
  const key = normalizeKey(item.title);
  const compact = compactKey(item.title);
  return maps.byTitle.get(key) || maps.byCompactTitle.get(compact) || {};
}

function normalizePriority(value) {
  const num = Number(value);
  return Number.isFinite(num) ? Math.max(0, Math.min(100, Math.round(num))) : 0;
}

function ensureNaturalSentence(text, fallback = '') {
  return normalizeText(text, 520) || normalizeText(fallback, 520);
}

function normalizeTier(list, type, maps) {
  if (!Array.isArray(list)) return [];
  return list.map((item) => {
    const source = getSourceArticle(item, maps);
    const base = {
      title: normalizeText(item.title) || source.title || '',
      titleZhNote: normalizeText(item.titleZhNote, 140),
      url: normalizeUrl(item.url) || source.url || '',
      journal: normalizeText(item.journal) || source.journal || '',
      date: normalizeText(item.date) || source.date || '',
    };

    if (type === 'tier3') {
      return {
        ...base,
        reason: normalizeText(item.reason, 220),
      };
    }

    const oneLinerSummary = ensureNaturalSentence(item.oneLinerSummary, item.mainFinding);
    const mainFinding = ensureNaturalSentence(item.mainFinding, oneLinerSummary);
    const assistantComment = ensureNaturalSentence(item.assistantComment, item.practicalTakeaway || item.clinicalTakeaway || mainFinding);

    return {
      ...base,
      priorityScore: normalizePriority(item.priorityScore),
      studyDesign: normalizeText(item.studyDesign, 180),
      oneLinerSummary,
      mainFinding,
      assistantComment,
    };
  });
}

function run($json, $items) {
  const streamErrorMessage = getStreamErrorMessage($json.text || $json.data || '');
  if (streamErrorMessage) throw new Error(`Model stream interrupted: ${streamErrorMessage}`);
  const modelOutput = getRawModelOutput($json);

  let parsed;
  let parseMode = 'strict';
  try {
    parsed = extractJson(modelOutput);
  } catch {
    parsed = salvageAnalysis(modelOutput);
    parseMode = 'salvaged';
  }

  let sourceArticles = [];
  try {
    const upstream = $items('Prepare Deep Review Input', 0, 0);
    if (upstream?.length) sourceArticles = upstream[0].json?.articles || [];
  } catch {}

  const articleMaps = buildArticleMaps(sourceArticles);
  const tier1 = normalizeTier(parsed.tier1, 'tier1', articleMaps);
  const tier2 = normalizeTier(parsed.tier2, 'tier2', articleMaps);
  const tier3 = normalizeTier(parsed.tier3, 'tier3', articleMaps);
  const total = tier1.length + tier2.length + tier3.length;

  const analysis = {
    headline: normalizeText(parsed.headline, 180) || '今日文獻快報',
    editorNote: normalizeText(parsed.editorNote, 420),
    counts: {
      total,
      tier1: tier1.length,
      tier2: tier2.length,
      tier3: tier3.length,
    },
    tier1,
    tier2,
    tier3,
  };

  return {
    json: {
      ...$json,
      analysis,
      text: JSON.stringify(analysis, null, 2),
      parseStatus: parseMode,
    }
  };
}

const result = run($json, $items);
return result;

function esc(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function paragraphize(text) {
  return esc(String(text ?? '')).replace(/\n+/g, '<br>');
}

function metaLine(item) {
  return [item.journal, item.date].filter(Boolean).map(esc).join(' | ');
}

const analysis = $json.analysis || {};
const tier1 = Array.isArray(analysis.tier1) ? analysis.tier1 : [];
const tier2 = Array.isArray(analysis.tier2) ? analysis.tier2 : [];
const tier3 = Array.isArray(analysis.tier3) ? analysis.tier3 : [];
const counts = analysis.counts || { total: tier1.length + tier2.length + tier3.length, tier1: tier1.length, tier2: tier2.length, tier3: tier3.length };

let summaryLine = `總篇數 ${counts.total || 0} 篇 ｜ Tier 1 ${counts.tier1 || 0} 篇 ｜ Tier 2 ${counts.tier2 || 0} 篇 ｜ Tier 3 ${counts.tier3 || 0} 篇`;
if (counts.shortlisted) {
  summaryLine = `總篇數 ${counts.total || 0} 篇 ｜ 深讀 ${counts.shortlisted || 0} 篇 ｜ Tier 1 ${counts.tier1 || 0} 篇 ｜ Tier 2 ${counts.tier2 || 0} 篇 ｜ Tier 3 ${counts.tier3 || 0} 篇`;
}

function renderTierCard(item, accent, bg) {
  return `<div style="background:${bg};border:1px solid #e6e0d7;border-radius:11px;padding:12px 13px;margin-bottom:10px;">
    <a href="${esc(item.url)}" style="font-size:15px;line-height:1.42;color:${accent};font-weight:700;text-decoration:none;">${esc(item.title)}</a>
    ${item.titleZhNote ? `<div style="font-size:12px;line-height:1.45;color:#6b2f26;margin-top:4px;"><a href="${esc(item.url)}" style="color:inherit;text-decoration:none;">${paragraphize(item.titleZhNote)}</a></div>` : ''}
    <div style="font-size:11px;color:#7b665d;margin-top:5px;">${metaLine(item)}${item.priorityScore ? ` ｜ 重要度 ${item.priorityScore}` : ''}</div>
    ${item.studyDesign ? `<p style="font-size:12px;color:#5a4d45;margin:9px 0 6px 0;"><strong>研究設計：</strong>${paragraphize(item.studyDesign)}</p>` : ''}
    ${item.oneLinerSummary ? `<p style="font-size:13px;color:#2f343a;margin:0 0 6px 0;"><strong>一句話總結：</strong>${paragraphize(item.oneLinerSummary)}</p>` : ''}
    ${item.mainFinding ? `<p style="font-size:13px;color:#33483a;margin:0 0 6px 0;"><strong>重點結果：</strong>${paragraphize(item.mainFinding)}</p>` : ''}
    ${item.assistantComment ? `<p style="font-size:12px;color:#6b2f26;margin:0;background:#f7f7f7;border-radius:8px;padding:7px 9px;"><strong>助理點評：</strong>${paragraphize(item.assistantComment)}</p>` : ''}
  </div>`;
}

let html = `
<div style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Arial,'Microsoft JhengHei',sans-serif;color:#243447;line-height:1.65;max-width:720px;margin:0 auto;padding:14px 10px;background:#f8f7f4;">
  <div style="background:#ffffff;border:1px solid #e6e0d7;border-radius:12px;padding:18px 16px;margin-bottom:14px;">
    <div style="font-size:12px;color:#5e554c;margin-bottom:6px;">頂級期刊臨床日報</div>
    <h1 style="font-size:21px;line-height:1.32;color:#7a1f3d;margin:0 0 8px 0;">${esc(analysis.headline || '今日頂級期刊臨床快報')}</h1>
    <p style="font-size:14px;color:#5e554c;margin:0 0 12px 0;">${paragraphize(analysis.editorNote || `臨床讀者好，今天共有 ${counts.total || 0} 篇文獻。`)}</p>
    <div style="font-size:12px;color:#57352d;background:#f7ede8;border-radius:10px;padding:8px 10px;display:inline-block;">${summaryLine}</div>
  </div>`;

if (tier1.length) {
  html += `<div style="background:#fff8f5;border:1px solid #ead9d1;border-radius:12px;padding:16px;margin-bottom:14px;"><h2 style="font-size:18px;color:#8a2744;margin:0 0 12px 0;">🔥 Tier 1 必讀重點</h2>`;
  for (const item of tier1) html += renderTierCard(item, '#8a2744', '#ffffff');
  html += '</div>';
}

if (tier2.length) {
  html += `<div style="background:#ffffff;border:1px solid #e6e0d7;border-radius:12px;padding:16px;margin-bottom:14px;"><h2 style="font-size:18px;color:#9a4f2d;margin:0 0 12px 0;">📑 Tier 2 實務更新</h2>`;
  for (const item of tier2) html += renderTierCard(item, '#9a4f2d', '#fbfcfd');
  html += '</div>';
}

if (tier3.length) {
  html += `<div style="background:#ffffff;border:1px solid #e6e0d7;border-radius:12px;padding:16px;margin-bottom:14px;"><h2 style="font-size:16px;color:#7f7a73;margin:0 0 10px 0;">📉 Tier 3 低優先文章</h2><ul style="padding-left:18px;margin:0;">`;
  for (const item of tier3) html += `<li style="font-size:12px;color:#7f7a73;margin-bottom:7px;"><a href="${esc(item.url)}" style="color:#7f7a73;text-decoration:none;">${esc(item.title)}</a>${item.titleZhNote ? ` ｜ <a href="${esc(item.url)}" style="color:#7f7a73;text-decoration:none;">${paragraphize(item.titleZhNote)}</a>` : ''}${item.reason ? ` - ${paragraphize(item.reason)}` : ''}</li>`;
  html += '</ul></div>';
}

html += `<div style="font-size:11px;color:#7b8794;text-align:center;padding:6px 0;">報告完畢</div></div>`;

return { json: { ...$json, html, text: html } };

function cleanText(value, maxLength = 0) {
  const text = String(value ?? '').replace(/\s+/g, ' ').trim();
  if (!maxLength || text.length <= maxLength) return text;
  return `${text.slice(0, maxLength)}...`;
}

let articles = Array.isArray($json?.articles) ? $json.articles : [];
if (!articles.length) {
  try {
    const upstream = $items("Build Detailed Digest", $itemIndex, 0);
    if (upstream?.length) {
      articles = upstream[0].json?.articles ?? [];
    }
  } catch (e) {
  }
}

const triageArticles = articles.map((article, index) => ({
  index: index + 1,
  title: cleanText(article.title, 300),
  url: cleanText(article.url),
  journal: cleanText(article.journal, 120),
  date: cleanText(article.date, 60),
}));

const payload = {
  reportDate: $json.reportDate || new Date().toISOString().slice(0, 10),
  articleCount: triageArticles.length,
  instruction: '這一輪只能用 title、journal、date 做標題初篩；不要假裝看過摘要。',
  articles: triageArticles,
};

const text = JSON.stringify(payload, null, 2);

return {
  json: {
    ...$json,
    articles,
    triageArticles,
    text,
    textPreview: text.slice(0, 500),
    length: text.length,
  }
};

function extractJson(raw) {
  const text = String(raw ?? '').trim();
  if (!text) throw new Error('Empty model output');

  const fenceMatch = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = fenceMatch ? fenceMatch[1].trim() : text;

  try {
    return JSON.parse(candidate);
  } catch (e) {
  }

  const start = candidate.indexOf('{');
  const end = candidate.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) throw new Error('JSON block not found');
  return JSON.parse(candidate.slice(start, end + 1));
}

function cleanText(value, maxLength = 0) {
  const text = String(value ?? '').replace(/\s+/g, ' ').trim();
  if (!maxLength || text.length <= maxLength) return text;
  return `${text.slice(0, maxLength)}...`;
}

function normalizePriority(value) {
  const num = Number(value);
  return Number.isFinite(num) ? Math.max(0, Math.min(100, Math.round(num))) : 0;
}

let fullArticles = Array.isArray($json?.articles) ? $json.articles : [];
if (!fullArticles.length) {
  try {
    const upstream = $items("Build Detailed Digest", $itemIndex, 0);
    if (upstream?.length) fullArticles = upstream[0].json?.articles ?? [];
  } catch (e) {
  }
}

const articleMap = new Map(fullArticles.map((article, idx) => [Number(article.index || idx + 1), {
  ...article,
  originalIndex: Number(article.index || idx + 1),
}]));

const parsed = extractJson($json.text);

function normalizeList(list, tier) {
  if (!Array.isArray(list)) return [];
  return list.map((item) => {
    const index = Number(item.index);
    const base = articleMap.get(index) || {
      originalIndex: index,
      index,
      title: item.title,
      url: item.url,
      journal: item.journal,
      date: item.date,
      summary: '',
      englishAbstract: '',
    };

    return {
      ...base,
      triageTier: tier,
      triageReason: cleanText(item.reason, 100),
      titleZhNote: cleanText(item.titleZhNote, 140),
      triagePriorityScore: normalizePriority(item.priorityScore),
      title: cleanText(base.title || item.title),
      url: cleanText(base.url || item.url),
      journal: cleanText(base.journal || item.journal),
      date: cleanText(base.date || item.date),
      englishAbstract: cleanText(base.englishAbstract || base.summary, 12000),
    };
  });
}

const candidateTier1 = normalizeList(parsed.candidateTier1, 'candidateTier1');
const candidateTier2 = normalizeList(parsed.candidateTier2, 'candidateTier2');
const seen = new Set([...candidateTier1, ...candidateTier2].map((item) => item.originalIndex));
let preTier3 = normalizeList(parsed.tier3, 'tier3').filter((item) => !seen.has(item.originalIndex));
for (const item of preTier3) seen.add(item.originalIndex);

for (const [index, article] of articleMap.entries()) {
  if (!seen.has(index)) {
    preTier3.push({
      ...article,
      triageTier: 'tier3',
      triageReason: '標題初看與基層實務關聯較低',
      titleZhNote: '',
      triagePriorityScore: 0,
    });
  }
}

const shortlistedArticles = [...candidateTier1, ...candidateTier2]
  .sort((a, b) => (b.triagePriorityScore || 0) - (a.triagePriorityScore || 0) || a.originalIndex - b.originalIndex);

const triage = {
  note: cleanText(parsed.note, 180) || '先用標題粗分流，保留較可能影響臨床實務的文章進入深讀。',
  counts: {
    total: fullArticles.length,
    candidateTier1: candidateTier1.length,
    candidateTier2: candidateTier2.length,
    tier3: preTier3.length,
  },
};

return {
  json: {
    ...$json,
    triage,
    shortlistedArticles,
    shortlistedCount: shortlistedArticles.length,
    preTier3: preTier3.map((item) => ({
      title: item.title,
      titleZhNote: item.titleZhNote,
      url: item.url,
      journal: item.journal,
      date: item.date,
      reason: cleanText(item.triageReason || '標題初看優先度較低', 80),
    })),
    parseStatus: 'ok',
    text: JSON.stringify({ triage, shortlistedCount: shortlistedArticles.length }, null, 2),
  }
};
